ALTER TABLE public.institution_additional_roles DROP CONSTRAINT institution_additional_roles_role_check;
ALTER TABLE public.institution_additional_roles ADD CONSTRAINT institution_additional_roles_role_check CHECK(role IN ('ministro_carino','ministro','asesor_especialidad','director_general'));
COMMENT ON COLUMN public.institution_additional_roles.role IS 'ministro_carino is deprecated: retained for historical rows only; new assignments use ministro.';
CREATE OR REPLACE FUNCTION public.assign_additional_institution_role(_inst uuid,_email text,_role text,_specialty text,_reports boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT coalesce(public.has_role(auth.uid(),'admin'),false) AND NOT coalesce(public.institution_role_of(_inst)::text='direccion',false) THEN RAISE EXCEPTION 'Solo dirección del centro o Max pueden asignar estos roles' USING ERRCODE='42501'; END IF; IF _role IS NULL OR _role NOT IN ('ministro','asesor_especialidad','director_general') OR _specialty IS NULL OR length(_specialty)>120 OR _reports IS NULL THEN RAISE EXCEPTION 'Rol inválido'; END IF; SELECT id INTO target FROM auth.users WHERE lower(email)=lower(btrim(_email)) AND email_confirmed_at IS NOT NULL; IF target IS NULL THEN RAISE EXCEPTION 'La persona debe confirmar primero su cuenta'; END IF; IF target=auth.uid() OR coalesce(public.has_role(target,'admin'),false) THEN RAISE EXCEPTION 'No puede modificar su propio rol ni una autoridad global' USING ERRCODE='42501'; END IF; IF NOT EXISTS(SELECT 1 FROM public.institution_members WHERE institution_id=_inst AND user_id=target) THEN RAISE EXCEPTION 'Asigne primero la persona a esta institución'; END IF; IF _role='ministro' AND _reports THEN RAISE EXCEPTION 'Ministro no concede acceso automático a informes'; END IF; IF _role='asesor_especialidad' AND btrim(_specialty)='' THEN RAISE EXCEPTION 'Indique la asignatura'; END IF; INSERT INTO public.institution_additional_roles VALUES(_inst,target,_role,btrim(_specialty),_reports,auth.uid(),now()) ON CONFLICT(institution_id,user_id,role) DO UPDATE SET specialty=excluded.specialty,can_read_reports=excluded.can_read_reports,assigned_by=excluded.assigned_by,assigned_at=excluded.assigned_at; INSERT INTO public.institution_additional_role_events(institution_id,user_id,role,specialty,can_read_reports,actor_id) VALUES(_inst,target,_role,btrim(_specialty),_reports,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.assign_additional_institution_role(uuid,text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.assign_additional_institution_role(uuid,text,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.lead_set_institution_member(_inst uuid,_email text,_role public.institution_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; oldrole public.institution_role; caller_admin boolean := coalesce(public.has_role(auth.uid(),'admin'),false); BEGIN IF NOT caller_admin AND NOT coalesce(public.institution_role_of(_inst)::text='direccion',false) THEN RAISE EXCEPTION 'Solo dirección del centro o Max pueden asignar roles' USING ERRCODE='42501'; END IF; IF _role IS NULL THEN RAISE EXCEPTION 'Seleccione un rol'; END IF; IF lower(btrim(_email)) NOT LIKE '%@gmail.com' THEN RAISE EXCEPTION 'Use una cuenta Gmail confirmada'; END IF; SELECT id INTO uid FROM auth.users WHERE lower(email)=lower(btrim(_email)) AND email_confirmed_at IS NOT NULL; IF uid IS NULL THEN RAISE EXCEPTION 'Cuenta confirmada no encontrada'; END IF; IF uid=auth.uid() THEN RAISE EXCEPTION 'No puede modificar su propio rol' USING ERRCODE='42501'; END IF; IF coalesce(public.has_role(uid,'admin'),false) THEN RAISE EXCEPTION 'Autoridad global protegida' USING ERRCODE='42501'; END IF; PERFORM 1 FROM public.institutions WHERE id=_inst FOR UPDATE; IF NOT caller_admin AND NOT coalesce(public.institution_role_of(_inst)::text='direccion',false) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; SELECT member_role INTO oldrole FROM public.institution_members WHERE institution_id=_inst AND user_id=uid FOR UPDATE; INSERT INTO public.institution_members(institution_id,user_id,member_role,verified_by) VALUES(_inst,uid,_role,auth.uid()) ON CONFLICT(institution_id,user_id) DO UPDATE SET member_role=excluded.member_role,verified_by=auth.uid(); INSERT INTO public.institution_role_events(institution_id,actor_id,user_id,previous_role,new_role) VALUES(_inst,auth.uid(),uid,oldrole::text,_role::text); RETURN uid; END $$;
REVOKE ALL ON FUNCTION public.lead_set_institution_member(uuid,text,public.institution_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.lead_set_institution_member(uuid,text,public.institution_role) TO authenticated;